                    local quality = canonicalQuality(txt)
                    local percent = parsePercent(txt)

                    if quality and percent ~= nil then
                        return quality, percent
                    end
                end

                return nil, nil
            end

            local function identityHint(item)
                if not item then
                    return nil
                end

                local attrs = item:GetAttributes()
                local keys = {
                    "UUID", "Uid", "UID",
                    "UniqueId", "UniqueID",
                    "ItemId", "ItemID",
                    "InventoryId", "InventoryID",
                }

                for _, key in ipairs(keys) do
                    local value = attrs[key]

                    if value ~= nil then
                        local s = tostring(value)

                        if s ~= "" then
                            if #s > 8 then
                                s = string.sub(s, -8)
                            end

                            return s
                        end
                    end
                end

                return nil
            end

            function M.BuildOptions()
                local inv = getInventory()
                local values = {}
                local counts = {}
                local ordinals = {}

                optionMap = {}
                optionMeta = {}

                if not inv then
                    return { "Select Item" }
                end

                local children = inv:GetChildren()

                for _, item in ipairs(children) do
                    counts[item.Name] = (counts[item.Name] or 0) + 1
                end

                for index, item in ipairs(children) do
                    local baseName = tostring(item.Name)
                    ordinals[baseName] = (ordinals[baseName] or 0) + 1

                    local ordinal = ordinals[baseName]
                    local quality, percent = readItemState(item, false)

                    local buffText = quality or "Unknown"
                    if percent ~= nil then
                        buffText = buffText
                            .. string.format(" %+.2f%%", percent)
                    end

                    local suffix = ""
                    if (counts[baseName] or 0) > 1 then
                        suffix = " #" .. tostring(ordinal)
                    end

                    local hint = identityHint(item)
                    if hint then
                        suffix = suffix .. " [" .. hint .. "]"
                    end

                    local label = baseName
                        .. " | "
                        .. buffText
                        .. suffix

                    if optionMap[label] then
                        label = label .. " @" .. tostring(index)
                    end

                    optionMap[label] = item
                    optionMeta[label] = {
                        Name = baseName,
                        Ordinal = ordinal,
                    }

                    table.insert(values, label)
                end

                table.sort(values)

                if #values == 0 then
                    table.insert(values, "Select Item")
                end

                return values
            end

            local function findItem(selection)
                local value = tostring(selection or "")

                if value == "" or value == "Select Item" then
                    return nil
                end

                local mapped = optionMap[value]
                if mapped and mapped.Parent then
                    return mapped
                end

                -- Rebuild once if Inventory changed.
                M.BuildOptions()

                mapped = optionMap[value]
                if mapped and mapped.Parent then
                    return mapped
                end

                local inv = getInventory()
                local fallbackName =
                    tostring(ctx.Config.ReforgeItemName or "")

                if inv and fallbackName ~= "" then
                    for _, item in ipairs(inv:GetChildren()) do
                        if item.Name == fallbackName then
                            return item
                        end
                    end
                end

                return nil
            end

            local function selectedItem()
                local selector =
                    tostring(ctx.Config.ReforgeItemSelector or "")

                if selector == "" then
                    selector = tostring(
                        ctx.Config.ReforgeItemName or ""
                    )
                end

                return findItem(selector)
            end

            local function goalState(item)
