                    return false, quality, percent
                end

                local currentRank = qualityRank[quality] or 0
                local targetRank =
                    qualityRank[ctx.Config.ReforgeTargetQuality] or 0
                local minPercent =
                    tonumber(ctx.Config.ReforgeMinPercent) or 0

