                local targetText =
                    tostring(
                        ctx.Config.ReforgeTargetQuality
                            or "Divine"
                    )
                    .. " / "
                    .. string.format(
                        "%+.2f%%",
                        tonumber(ctx.Config.ReforgeMinPercent) or 0
                    )

