            function M.UpdateStatus()
                if not ctx.Paragraph
                    or type(ctx.Paragraph.SetContent)
                        ~= "function" then
                    return
                end

                local ok, content = pcall(statusText)

                if not ok or type(content) ~= "string" then
                    return
                end

                if content == lastStatusText then
                    return
                end

                lastStatusText = content

                pcall(function()
                    ctx.Paragraph:SetContent(content)
                end)
            end

            function M.SetDropdown(obj)
                dropdown = obj
            end

            function M.Select(selected)
                local value =
                    type(selected) == "table"
                    and (selected[1] or next(selected))
                    or selected

                value = tostring(value or "")

                ctx.Config.ReforgeItemSelector = value

                local item = findItem(value)
                ctx.Config.ReforgeItemName =
                    item and item.Name or ""

                cachedResultLabel = nil
                save()
                M.UpdateStatus()
            end

            function M.SetQuality(selected)
                local value =
                    type(selected) == "table"
                    and (selected[1] or next(selected))
                    or selected

                ctx.Config.ReforgeTargetQuality =
                    tostring(value or "Divine")

                save()
                M.UpdateStatus()
            end

            function M.SetMinPercent(value)
                ctx.Config.ReforgeMinPercent =
                    tonumber(value) or 5

                save()
                M.UpdateStatus()
            end

            function M.SetMaxAttempts(value)
                ctx.Config.ReforgeMaxAttempts =
                    math.floor(tonumber(value) or 100)

                save()
                M.UpdateStatus()
            end

