                local values = M.BuildOptions()

                if dropdown
                    and type(dropdown.SetValues)
                        == "function" then
                    pcall(function()
                        dropdown:SetValues(values)
                    end)
                end

                M.UpdateStatus()

                notify(
                    "Auto Reforge",
                    "Reforge item list refreshed.",
                    3
                )
            end

            function M.Inspect()
                local item = selectedItem()

                if not item then
                    notify(
                        "Auto Reforge",
                        "No item selected.",
                        3
                    )
                    return
                end

                cachedResultLabel = nil

                local quality, percent =
                    readItemState(item, true)

                local textValue = quality or "Unknown"

                if percent ~= nil then
                    textValue = textValue
                        .. string.format(
                            " (%+.2f%%)",
                            percent
                        )
                end

                notify(
                    "Reforge State",
                    textValue,
                    5
                )

                M.UpdateStatus()
            end

