                        or not upgradeRemote:IsA(
                            "RemoteFunction"
                        ) then

                        ctx.Config.AutoReforge = false
                        busy = false
                        save()
                        M.UpdateStatus()
                        return
                    end

                    local maxAttempts = math.clamp(
                        tonumber(
                            ctx.Config.ReforgeMaxAttempts
                        ) or 100,
                        1,
                        500
                    )

                    local unknownReads = 0

                    while ctx.Config.AutoReforge
                        and attempts < maxAttempts do

                        local item = selectedItem()

                        if not item or not item.Parent then
                            break
                        end

                        local goalMet, quality, percent =
                            goalState(item)

                        if goalMet then
                            break
